:root {
  --color-primary: #3B82F6;
  --color-primary-hover: #2563EB;
  --color-primary-active: #1D4ED8;
  --color-primary-foreground: #FFFFFF;
  --color-secondary: #64748B;
  --color-secondary-foreground: #FFFFFF;
  --color-background: #0F172A;
  --color-surface: #F8FAFC;
  --color-surface-card: #F8FAFC;
  --color-surface-elevated: #334155;
  --color-text: #F8FAFC;
  --color-text-muted: #94A3B8;
  --color-text-subtle: #64748B;
  --color-text-inverse: #0F172A;
  --color-border: #334155;
  --color-border-light: #475569;
  --color-border-focus: #3B82F6;
  --color-accent: rgba(59, 130, 246, 0.15);
  --color-success: #10B981;
  --color-warning: #F59E0B;
  --color-error: #EF4444;
  --color-info: #06B6D4;
  --font-sans: Inter, system-ui, sans-serif;
  --font-serif: Georgia, serif;
  --font-mono: Fira Code, monospace;
  --font-display: Inter, system-ui, sans-serif;
  --text-xs: 12px;
  --text-sm: 14px;
  --text-base: 16px;
  --text-md: 18px;
  --text-lg: 20px;
  --text-xl: 24px;
  --text-2xl: 30px;
  --text-3xl: 36px;
  --text-4xl: 48px;
  --space-0: 0px;
  --space-1: 4px;
  --space-2: 8px;
  --space-3: 12px;
  --space-4: 16px;
  --space-5: 20px;
  --space-6: 24px;
  --space-8: 32px;
  --space-10: 40px;
  --space-12: 48px;
  --space-16: 64px;
  --space-20: 80px;
  --space-24: 96px;
  --radius-none: 0px;
  --radius-sm: 4px;
  --radius-md: 9999px;
  --radius-lg: 12px;
  --radius-xl: 16px;
  --radius-full: 9999px;
  --shadow-none: none;
  --shadow-sm: 0 4px 12px rgba(59, 130, 246, 0.25);
  --shadow-md: 0 4px 6px -1px rgba(0, 0, 0, 0.1);
  --shadow-lg: 0 10px 15px -3px rgba(0, 0, 0, 0.1), 0 4px 6px -2px rgba(0, 0, 0, 0.05);
  --shadow-xl: 0 20px 25px -5px rgba(0, 0, 0, 0.1), 0 10px 10px -5px rgba(0, 0, 0, 0.04);
  --shadow-inner: inset 0 2px 4px 0 rgba(0, 0, 0, 0.06);
}

*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html, body, #root {
  width: 100%;
  min-height: 100%;
  font-family: var(--font-sans);
  background-color: var(--color-background);
  color: var(--color-text);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

button {
  font-family: inherit;
  cursor: pointer;
  border: none;
  background: none;
  transition: all 0.2s ease-in-out;
}

button:hover {
  filter: brightness(1.08);
}

button:active {
  transform: translateY(1px);
}

input, textarea, select {
  font-family: inherit;
  font-size: inherit;
  outline: none;
}

a {
  color: inherit;
  text-decoration: none;
}

/* Base utility classes derived from UI IR */
.aiui-page {
  display: flex;
  flex-direction: column;
  min-height: 100vh;
  width: 100%;
  background-color: var(--color-background);
  color: var(--color-text);
}

.aiui-container {
  width: 100%;
  max-width: 1280px;
  margin: 0 auto;
}

.aiui-card {
  background-color: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  box-shadow: var(--shadow-md);
}

.aiui-glass {
  background: rgba(30, 41, 59, 0.7);
  backdrop-filter: blur(12px);
  border: 1px solid rgba(255, 255, 255, 0.1);
}

import React from 'react';
import HeaderNavigation from './components/HeaderNavigation.jsx';
import HeroSection from './components/HeroSection.jsx';
import FeaturesGrid from './components/FeaturesGrid.jsx';

export default function App() {
  return (
    <div className="aiui-page" style={{"backgroundColor":"#0F172A","color":"#F8FAFC","fontFamily":"Inter, system-ui, sans-serif"}}>
      <HeaderNavigation />
      <HeroSection />
      <FeaturesGrid />
    </div>
  );
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App.jsx';
import './index.css';

ReactDOM.createRoot(document.getElementById('root')).render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

import { defineConfig } from 'vite';
import react from '@vitejs/plugin-react';

export default defineConfig({
  plugins: [react()],
  server: {
    port: 3000,
    host: '127.0.0.1',
  },
});

